SET LOCAL ROLE service_role;
SELECT set_config('chat.session',public.prepare_chat_media_upload(null,repeat('a',64),'93000000-0000-0000-0000-000000000001','92000000-0000-0000-0000-000000000001','94000000-0000-0000-0000-000000000001',100,'image/png','chat.png')->>'session_id',true);
SELECT pg_temp.assert(public.prepare_chat_media_upload(null,repeat('a',64),'93000000-0000-0000-0000-000000000001','92000000-0000-0000-0000-000000000001','94000000-0000-0000-0000-000000000001',100,'image/png','chat.png')->>'session_id'=current_setting('chat.session'),'guest prepare retry stable');
