SELECT pg_temp.assert(public.resolve_chat_media(null,repeat('b',64),current_setting('chat.asset')::uuid) IS NULL,'other guest denied binary');
SELECT pg_temp.expect_error($q$SELECT public.post_public_chat_message_media('94000000-0000-0000-0000-000000000002','92000000-0000-0000-0000-000000000001',(SELECT updated_at FROM public.chat_conversation WHERE id='92000000-0000-0000-0000-000000000001'),null,repeat('a',64),'image','image',false,1,null,true,true,ARRAY[current_setting('chat.asset')::uuid])$q$,'42501');
